def parse_raw_command_output(command_class, raw_command_output, command_params=None):
    """

    :param command_class: eg any moler cmd class eg Iptables (from moler.cmd.unix.iptables import Iptables)
    :param raw_command_output: Sample output from terminal
    :param command_params: dict of command params
    :return:
    """
    if command_params is None:
        command_params = {}
    cmd = command_class(connection=None, **command_params)
    cmd._cmd_output_started = True
    cmd.data_received(raw_command_output, None)
    return cmd.current_ret
